{
  "name": "E-255压电定位器",
  "name_en": "E-255 Piezo Positioner",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "用于显微实验中的高精度压电定位设备，可按通道移动到指定位置并读取当前位置、行程上下限、控制就绪状态以及部分通道信息，常用于精密调焦或纳米级位移控制。",
  "description_en": "A high-precision piezo positioning device for microscopy experiments. It can move a channel to a target position and report current position, travel limits, controller ready status, and channel-related information. It is typically used for fine focus or nanometer-scale motion control.",
  "actions": [
    {
      "action_name": "auto-MoveTo",
      "description": "将指定通道移动到目标位置。",
      "description_en": "Move the specified channel to a target position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "读取指定通道的当前位置。",
      "description_en": "Read the current position of the specified channel."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "获取控制是否就绪状态。",
      "description_en": "Get whether the controller is ready."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "获取通道对象信息。",
      "description_en": "Get channel object information."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "获取通道相位信息。",
      "description_en": "Get channel phase information."
    },
    {
      "action_name": "auto-GetMin",
      "description": "获取指定通道的最小位置限值。",
      "description_en": "Get the minimum position limit of the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "获取指定通道的最大位置限值。",
      "description_en": "Get the maximum position limit of the specified channel."
    }
  ],
  "tag_hints": [
    "piezo positioning",
    "nanopositioning",
    "microscope focus control",
    "precision motion",
    "travel limits",
    "PI E-255"
  ]
}

